Method.Source:
    /// <summary>
    /// get lastest transfer order number and recVersion as reference
    /// </summary>
    /// <returns>sales confirmation number</returns>
    private static server str confirmationDocumentReference()
    {

        DataEntityName      dataEntityName= tablestr(METWMSTransferPickingRouteEntity);
        List                fieldList = new List(types::String);

        fieldList.addEnd(SysComputedColumn::returnField(DataEntityName, identifierstr(InventTransferTable), fieldstr(InventTransferTable, TransferId)));
        fieldList.addEnd(SysComputedColumn::returnLiteral("-"));
        fieldList.addEnd(SysComputedColumn::cast(SysComputedColumn::returnField(DataEntityName, identifierstr(InventTransferTable), fieldstr(InventTransferTable, RecVersion)), "NVARCHAR"));
        
        return SysComputedColumn::addList(fieldList);
    }

    /// <summary>
    /// Method to build the computed columns for CutOffDay and CutOffTime
    /// </summary>
    /// <param name = "_returnFieldIdFromRouteStopTable">Parameter to specify if we want the computed column to return CutOffDay or CutOffTime from METRouteStopTable</param>
    /// <param name = "_returnFieldIdFromRouteTable">Parameter to specify if we want the computed column to return CutOffDay or CutOffTime from METRouteTable</param>
    /// <returns>Computed column SQL statement</returns>
    private static server str buildComputedColumns(FieldId _returnFieldIdFromRouteStopTable, FieldId _returnFieldIdFromRouteTable)
    {
        SysDictTable metRouteStopTable = new SysDictTable(tableNum(METRouteStopTable));
        SysDictTable metRouteTable = new SysDictTable(tableNum(METRouteTable));

        str routeStopIdValue = SysComputedColumn::returnField(tablestr(METWMSTransferPickingRouteEntity), dataEntityDataSourceStr(METWMSTransferPickingRouteEntity, METInventTransferTableExt), fieldStr(METInventTransferTableExt, RouteStopNum));

        str routeIdValue = SysComputedColumn::returnField(tablestr(METWMSTransferPickingRouteEntity), dataEntityDataSourceStr(METWMSTransferPickingRouteEntity, METInventTransferTableExt), fieldStr(METInventTransferTableExt, Route));
        
        str routeStopIdentifierValue = SysComputedColumn::returnField(tablestr(METWMSTransferPickingRouteEntity), dataEntityDataSourceStr(METWMSTransferPickingRouteEntity, METInventTransferTableExt), fieldStr(METInventTransferTableExt, RouteStopIdentifier));

        str routeIdentifierValue = SysComputedColumn::returnField(tablestr(METWMSTransferPickingRouteEntity), dataEntityDataSourceStr(METWMSTransferPickingRouteEntity, METInventTransferTableExt), fieldStr(METInventTransferTableExt, RouteIdentifier));


        // RouteStopNum (updated)
        str existRouteStopIdSql = strFmt(
            @"EXISTS (
            SELECT 'x' FROM %1
                WHERE %1.%2 = %3 AND
                      %1.%4 = %5
            )",
            metRouteStopTable.name(),
            metRouteStopTable.fieldName(fieldNum(METRouteStopTable, RouteStopId)),
            routeStopIdValue,
            metRouteStopTable.fieldName(fieldNum(METRouteStopTable, RouteId)),
            routeIdValue);

        str routeStopIdSql = strFmt(
            @"(SELECT TOP 1 %1.%3 FROM %1
                WHERE %1.%2 = %4 AND
                      %1.%5 = %6
            )",
            metRouteStopTable.name(),
            metRouteStopTable.fieldName(fieldNum(METRouteStopTable, RouteStopId)),
            metRouteStopTable.fieldName(_returnFieldIdFromRouteStopTable),
            routeStopIdValue,
            metRouteStopTable.fieldName(fieldNum(METRouteStopTable, RouteId)),
            routeIdValue);

        // RouteStopNum (original)
        str existOriginalRouteStopIdSql = strFmt(
            @"EXISTS (
            SELECT 'x' FROM %1
                WHERE %1.%2 = %3
            )",
            metRouteStopTable.name(),
            metRouteStopTable.fieldName(fieldNum(METRouteStopTable, RouteStopIdentifier)),
            routeStopIdentifierValue);

        str originalRouteStopIdSql = strFmt(
            @"(SELECT TOP 1 %1.%3 FROM %1
                WHERE %1.%2 = %4
            )",
            metRouteStopTable.name(),
            metRouteStopTable.fieldName(fieldNum(METRouteStopTable, RouteStopIdentifier)),
            metRouteStopTable.fieldName(_returnFieldIdFromRouteStopTable),
            routeStopIdentifierValue);

        // Route (updated)
        str existRouteIdSql = strFmt(
            @"EXISTS (
            SELECT 'x' FROM %1
                WHERE %1.%2 = %3
            )",
            metRouteTable.name(),
            metRouteTable.fieldName(fieldNum(METRouteTable, RouteId)),
            routeIdValue);

        str routeIdSql = strFmt(
            @"(SELECT TOP 1 %1.%3 FROM %1
                WHERE %1.%2 = %4
            )",
            metRouteTable.name(),
            metRouteTable.fieldName(fieldNum(METRouteTable, RouteId)),
            metRouteTable.fieldName(_returnFieldIdFromRouteTable),
            routeIdValue);

        // Route (original)
        str existOriginalRouteIdSql = strFmt(
            @"EXISTS (
            SELECT 'x' FROM %1
                WHERE %1.%2 = %3
            )",
            metRouteTable.name(),
            metRouteTable.fieldName(fieldNum(METRouteTable, RouteIdentifier)),
            routeIdentifierValue);

        str originalRouteIdSql = strFmt(
            @"(SELECT TOP 1 %1.%3 FROM %1
                WHERE %1.%2 = %4
            )",
            metRouteTable.name(),
            metRouteTable.fieldName(fieldNum(METRouteTable, RouteIdentifier)),
            metRouteTable.fieldName(_returnFieldIdFromRouteTable),
            routeIdentifierValue);

        return SysComputedColumn::if(existRouteStopIdSql, routeStopIdSql,
                    SysComputedColumn::if(existOriginalRouteStopIdSql, originalRouteStopIdSql,
                        SysComputedColumn::if(existRouteIdSql, routeIdSql,
                            SysComputedColumn::if(existOriginalRouteIdSql, originalRouteIdSql, int2Str(0)))));
    }

/// <summary>
/// Method to build the computed columns for CutOffDay
/// </summary>
/// <returns></returns>
private static server str cutOffDay()
{
    return METWMSTransferPickingRouteEntity::buildComputedColumns(fieldNum(METRouteStopTable, OrderCutOffDay), fieldNum(METRouteTable, OrderCutOffDay)/*), "INT"*/);
}

/// <summary>
/// Method to build the computed columns for CutOffTime
/// </summary>
/// <returns>Computed column SQL statement</returns>
private static server str cutOffTime()
{
    return METWMSTransferPickingRouteEntity::buildComputedColumns(fieldNum(METRouteStopTable, OrderCutOffTime), fieldNum(METRouteTable, OrderCutOffTime));
}
